        vertlist[1] = vertex_interp (v[1], v[2], f[1], f[2]);
        vertlist[2] = vertex_interp (v[2], v[3], f[2], f[3]);
        vertlist[3] = vertex_interp (v[3], v[0], f[3], f[0]);
        vertlist[4] = vertex_interp (v[4], v[5], f[4], f[5]);
