        __device__ __forceinline__ T scan_block( volatile T *ptr , const unsigned int idx = threadIdx.x )
        {        
            const unsigned int lane = idx & 31;
            const unsigned int warpid = idx >> 5;

            // Step 1: Intra - warp scan in each warp
