  compactionKernel<<<grid, block>>>(c);
  cudaSafeCall( cudaGetLastError() );
  cudaSafeCall( cudaStreamSynchronize(0) );

  verts_inds.swap(verts_inds2);
  head_points.swap(head_points2);
