      unsigned* finished;
'''+s[idx:]
 a=s.index('if (lane == 0) gbuf.ptr(e)');b=s.index('\n',a)
 insert='''
        }
        // All matrix-entry writers publish their partials before the block
        // reports completion. The counter is workspace-local and wraps to zero.
        if (lane == 0) __threadfence();
        __syncthreads();
        __shared__ bool last;
        if (tid == 0)
          last = atomicInc(finished, gridDim.x * gridDim.y - 1) == gridDim.x * gridDim.y - 1;
        __syncthreads();
        if (last) {
          int length = gridDim.x * gridDim.y;
          for (int e = warp; e < 27; e += 8) {
            const volatile float_type* src = gbuf.ptr(e);
            float_type v[16];
            #pragma unroll
            for (int k = 0; k < 16; ++k) {
              v[k] = 0.;
              for (int i = lane + 32*k; i < length; i += 512) v[k] += src[i];
            }
            #pragma unroll
            for (int step = 8; step; step >>= 1)
